package com.crm.customer.entity;import jakarta.persistence.*;import lombok.Data;import java.time.LocalDateTime;
@Entity @Table(name="client_case_events") @Data public class ClientCaseEvent {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(name="case_id",nullable=false,updatable=false) private Long caseId;@Column(nullable=false,length=20,updatable=false) private String status;@Column(name="author_id",nullable=false,updatable=false) private Long authorId;@Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt;@PrePersist void created(){createdAt=LocalDateTime.now();}}
